"""Apprentissage automatique : notions générales, modèles, entraînement, évaluation, apprentissage par renforcement."""
from __future__ import annotations

from patrick.knowledge.dictionary import d

T = "ml"
TERMS = [
    d(T, "apprentissage_supervise", "Apprentissage supervisé et non supervisé", "Supervised and unsupervised learning", 1,
      "En apprentissage supervisé, le modèle apprend à prédire une cible connue (hausse ou baisse) à partir de variables ; en non supervisé, il cherche une structure sans cible (groupes, facteurs). La plupart des modèles de PATRICK sont supervisés.",
      "In supervised learning the model learns to predict a known target (up or down) from features; in unsupervised learning it looks for structure without a target (clusters, factors). Most PATRICK models are supervised.",
      see="feature_engineering exp_pca"),
    d(T, "surapprentissage", "Surapprentissage (overfitting)", "Overfitting", 2,
      "Le modèle apprend le bruit de l'échantillon d'entraînement au lieu du signal : excellent sur les données vues, mauvais sur les nouvelles. C'est le danger central en finance, où le rapport signal/bruit est très faible et où l'on peut essayer des milliers de modèles.",
      "The model learns the training sample's noise instead of the signal: excellent on seen data, poor on new data. It is the central danger in finance, where the signal-to-noise ratio is very low and thousands of models can be tried.",
      see="biais_variance validation_croisee data_snooping"),
    d(T, "biais_variance", "Compromis biais–variance", "Bias–variance trade-off", 2,
      "Un modèle trop simple se trompe systématiquement (biais élevé) ; un modèle trop souple s'adapte au bruit (variance élevée). L'erreur hors échantillon est minimale à un compromis, que la régularisation et la validation aident à trouver.",
      "A model too simple errs systematically (high bias); a model too flexible fits noise (high variance). Out-of-sample error is minimal at a compromise, which regularisation and validation help find.",
      see="surapprentissage regularisation estimateur_biais"),
    d(T, "jeux_train_val_test", "Jeux d'entraînement, de validation et de test", "Training, validation and test sets", 1,
      "Le jeu d'entraînement ajuste les paramètres ; le jeu de validation règle les hyperparamètres ; le jeu de test, intouché jusqu'à la fin, estime la performance réelle. En séries temporelles, ces jeux se succèdent dans le temps, jamais mélangés.",
      "The training set fits parameters; the validation set tunes hyperparameters; the test set, untouched until the end, estimates real performance. In time series these sets follow each other in time, never shuffled.",
      see="validation_croisee holdout walk_forward"),
    d(T, "validation_croisee", "Validation croisée", "Cross-validation", 2,
      "Évaluer un modèle en le réentraînant sur plusieurs découpages des données et en moyennant l'erreur sur les parties mises de côté. La version classique mélange les dates et fuit en séries temporelles ; on utilise des variantes avec purge et embargo.",
      "Evaluating a model by retraining on several splits of the data and averaging error on the held-out parts. The classic version shuffles dates and leaks in time series; variants with purge and embargo are used.",
      see="purge embargo_enabled walk_forward"),
    d(T, "feature_engineering", "Variables explicatives (features)", "Features (feature engineering)", 2,
      "Grandeurs calculées à partir des données brutes pour aider le modèle : rendements passés, volatilité récente, écart à une moyenne mobile, indicateurs macro. Leur construction ne doit utiliser que l'information disponible à la date de décision.",
      "Quantities computed from raw data to help the model: past returns, recent volatility, gap to a moving average, macro indicators. Their construction must only use information available at the decision date.",
      see="technical biais_look_ahead"),
    d(T, "normalisation_standardisation", "Normalisation et standardisation", "Normalisation and standardisation", 2,
      "Ramener les variables à une échelle comparable (moyenne 0 et écart-type 1, ou entre 0 et 1) pour les réseaux de neurones et les modèles pénalisés. Les moyennes et écarts-types se calculent sur l'entraînement seul, sinon c'est une fuite.",
      "Bringing features to a comparable scale (mean 0 and standard deviation 1, or between 0 and 1) for neural networks and penalised models. Means and standard deviations are computed on training alone, otherwise it is a leak.",
      see="feature_engineering data_leak"),
    d(T, "regularisation", "Régularisation (L1, L2, ridge)", "Regularisation (L1, L2, ridge)", 3,
      "Pénalité ajoutée à la fonction de perte pour limiter la taille des coefficients : L2 (ridge) les rétrécit tous, L1 (lasso) en annule certains. Elle réduit la variance au prix d'un peu de biais et stabilise les modèles sur des données bruitées.",
      "Penalty added to the loss to limit coefficient size: L2 (ridge) shrinks them all, L1 (lasso) zeroes some. It reduces variance at the cost of some bias and stabilises models on noisy data.",
      formula=r"\min_\beta \;\|y-X\beta\|^2 + \lambda\,\|\beta\|_2^2", see="lasso biais_variance"),
    d(T, "arbre_de_decision", "Arbre de décision", "Decision tree", 2,
      "Modèle qui pose une suite de questions oui/non sur les variables (« volatilité > 20 % ? ») pour aboutir à une prévision. Lisible, mais instable et facilement sur-ajusté : on l'utilise surtout en forêts et en boosting.",
      "Model asking a series of yes/no questions about features ('volatility > 20%?') to reach a forecast. Readable, but unstable and easily overfit: used mostly in forests and boosting.",
      see="RandomForest GradientBoosting"),
    d(T, "bagging_boosting", "Bagging et boosting", "Bagging and boosting", 3,
      "Deux façons de combiner de nombreux modèles faibles : le bagging les entraîne en parallèle sur des échantillons tirés au hasard et moyenne (forêt aléatoire) ; le boosting les entraîne l'un après l'autre, chacun corrigeant les erreurs du précédent (XGBoost, LightGBM).",
      "Two ways to combine many weak models: bagging trains them in parallel on random samples and averages (random forest); boosting trains them one after another, each correcting the previous one's errors (XGBoost, LightGBM).",
      see="RandomForest XGBoost LightGBM"),
    d(T, "hyperparametre", "Hyperparamètre", "Hyperparameter", 2,
      "Réglage du modèle fixé avant l'entraînement et non appris (profondeur d'un arbre, taux d'apprentissage, nombre d'époques). Le choisir sur le jeu de validation, jamais sur le jeu de test.",
      "Model setting fixed before training and not learned (tree depth, learning rate, number of epochs). Choose it on the validation set, never the test set.",
      see="optimisation_bayesienne jeux_train_val_test"),
    d(T, "optimisation_bayesienne", "Optimisation bayésienne (Optuna)", "Bayesian optimisation (Optuna)", 3,
      "Méthode de recherche d'hyperparamètres qui modélise la performance déjà observée pour choisir les prochains essais prometteurs, au lieu de tout tester. Chaque essai compte dans le nombre d'essais à corriger quand on juge le résultat.",
      "Hyperparameter search method that models performance already observed to choose promising next trials, instead of testing everything. Each trial counts toward the number of trials to correct for when judging the result.",
      see="hyperparametre n_trials"),
    d(T, "selection_de_variables", "Sélection de variables", "Feature selection", 2,
      "Garder les variables utiles et écarter le reste, pour réduire le bruit et le surapprentissage : filtres, élimination récursive (RFE), pénalité L1. Elle doit se faire à l'intérieur de chaque pli d'entraînement, sinon elle fuit l'information du test.",
      "Keeping useful features and dropping the rest, to cut noise and overfitting: filters, recursive elimination (RFE), L1 penalty. It must be done inside each training fold, otherwise it leaks test information.",
      see="rfe lasso shap"),
    d(T, "importance_permutation", "Importance par permutation", "Permutation importance", 3,
      "Mesure l'utilité d'une variable par la perte de performance quand on mélange ses valeurs au hasard. Simple et valable pour tout modèle ; trompeuse quand des variables sont très corrélées entre elles.",
      "Measures a feature's usefulness by the performance loss when its values are randomly shuffled. Simple and valid for any model; misleading when features are highly correlated with each other.",
      see="shap selection_de_variables"),
    d(T, "reseau_neurones", "Réseau de neurones", "Neural network", 3,
      "Empilement de couches de calculs simples (combinaisons linéaires suivies d'une non-linéarité) dont les poids sont appris par descente de gradient. Très flexible, il exige beaucoup de données ; sur des données financières bruitées, il sur-apprend facilement.",
      "Stack of layers of simple computations (linear combinations followed by a non-linearity) whose weights are learned by gradient descent. Very flexible, it needs lots of data; on noisy financial data it overfits easily.",
      see="descente_gradient MLP LSTM", alias="deep learning"),
    d(T, "descente_gradient", "Descente de gradient et rétropropagation", "Gradient descent and backpropagation", 3,
      "On ajuste les poids dans la direction qui réduit la fonction de perte, par petits pas (taux d'apprentissage). La rétropropagation calcule efficacement le gradient couche par couche. Un pas trop grand diverge, trop petit apprend trop lentement.",
      "Weights are adjusted in the direction reducing the loss function, in small steps (learning rate). Backpropagation efficiently computes the gradient layer by layer. A step too large diverges, too small learns too slowly.",
      formula=r"w \leftarrow w - \eta\,\nabla_w \mathcal{L}", see="reseau_neurones dl_learning_rate"),
    d(T, "fonction_de_perte", "Fonction de perte", "Loss function", 2,
      "Mesure de l'erreur que l'entraînement cherche à minimiser : erreur quadratique pour une valeur continue, entropie croisée pour une classe. Choisir la perte qui correspond à la décision réelle compte autant que le modèle.",
      "Error measure that training tries to minimise: squared error for a continuous value, cross-entropy for a class. Choosing the loss matching the real decision matters as much as the model.",
      see="entropie_croisee qlike"),
    d(T, "entropie_croisee", "Entropie croisée", "Cross-entropy", 3,
      "Perte utilisée en classification qui pénalise fortement les probabilités confiantes mais fausses : −Σ y ln(p). Elle favorise des probabilités bien calibrées ; son équivalent binaire est la perte logarithmique.",
      "Loss used in classification that heavily penalises confident but wrong probabilities: −Σ y ln(p). It favours well-calibrated probabilities; its binary equivalent is the log loss.",
      formula=r"-\sum_c y_c \ln p_c", see="fonction_de_perte calibration", alias="log loss"),
    d(T, "matrice_confusion", "Matrice de confusion, précision et rappel", "Confusion matrix, precision and recall", 2,
      "Tableau croisant classes prédites et classes réelles. La précision est la part des prédictions « hausse » qui sont justes ; le rappel est la part des vraies hausses détectées. Un modèle peut avoir une bonne précision et un mauvais rappel, ou l'inverse.",
      "Table crossing predicted and actual classes. Precision is the share of 'up' predictions that are right; recall is the share of true rises detected. A model can have good precision and poor recall, or the reverse.",
      see="f1 auc balanced_accuracy"),
    d(T, "courbe_roc", "Courbe ROC", "ROC curve", 2,
      "Trace le taux de vrais positifs contre le taux de faux positifs quand on fait varier le seuil de décision. L'aire sous la courbe (AUC) vaut 0,5 pour le hasard et 1 pour un modèle parfait ; sur des marchés, 0,52 à 0,55 est déjà un résultat sérieux.",
      "Plots the true-positive rate against the false-positive rate as the decision threshold varies. The area under the curve (AUC) is 0.5 for chance and 1 for a perfect model; in markets, 0.52 to 0.55 is already a serious result.",
      see="auc matrice_confusion"),
    d(T, "desequilibre_classes", "Déséquilibre de classes", "Class imbalance", 2,
      "Quand une classe est bien plus fréquente qu'une autre (peu de grosses baisses), un modèle peut avoir une bonne exactitude en prédisant toujours la classe majoritaire. On rééquilibre (pondération, SMOTE) et on juge par des métriques adaptées (F1, balanced accuracy).",
      "When one class is far more frequent than another (few large drops), a model can score high accuracy by always predicting the majority class. One rebalances (weighting, SMOTE) and judges with suitable metrics (F1, balanced accuracy).",
      see="SMOTE balanced_accuracy f1"),
    d(T, "apprentissage_ensemble", "Apprentissage d'ensemble", "Ensemble learning", 3,
      "Combiner plusieurs modèles différents (moyenne, vote, empilement) : leurs erreurs se compensent en partie, donc l'ensemble est souvent meilleur et plus stable que chacun. Le gain est d'autant plus grand que les modèles sont diversifiés.",
      "Combining several different models (average, vote, stacking): their errors partly offset, so the ensemble is often better and more stable than each. The gain is larger the more diverse the models.",
      see="stacking bagging_boosting"),
    d(T, "clustering_kmeans", "Classification non supervisée (k-means)", "Clustering (k-means)", 3,
      "Regroupe des observations ou des actifs en k groupes de comportements proches. En finance, sert à définir des régimes de marché ou des familles d'actifs (par exemple pour HRP) sans présupposé.",
      "Groups observations or assets into k groups of similar behaviour. In finance it defines market regimes or asset families (for example for HRP) with no presupposition.",
      see="hrp regime"),
    d(T, "autoencodeur", "Autoencodeur", "Autoencoder", 3,
      "Réseau qui apprend à compresser puis reconstruire ses entrées : la couche intermédiaire résume l'information essentielle. Utilisé pour débruiter, réduire la dimension ou détecter des anomalies, comme une ACP non linéaire.",
      "Network learning to compress then reconstruct its inputs: the middle layer summarises the essential information. Used to denoise, reduce dimension or detect anomalies, like a non-linear PCA.",
      see="exp_pca reseau_neurones"),
    d(T, "apprentissage_renforcement_notions", "Apprentissage par renforcement : notions", "Reinforcement learning: concepts", 3,
      "Un agent observe un état, choisit une action, reçoit une récompense et apprend une politique qui maximise la récompense cumulée. En finance, l'action est une position, la récompense un gain ajusté du risque et des coûts ; l'environnement est un historique de marché rejoué.",
      "An agent observes a state, picks an action, receives a reward and learns a policy maximising cumulative reward. In finance the action is a position, the reward a risk- and cost-adjusted gain; the environment is a replayed market history.",
      see="rl_policy rl_reward rl_agent"),
    d(T, "exploration_exploitation", "Exploration et exploitation", "Exploration vs exploitation", 3,
      "Dilemme de l'agent : exploiter ce qu'il sait marcher ou explorer de nouvelles actions pour apprendre. Trop d'exploitation fige une stratégie médiocre ; trop d'exploration coûte cher en conditions réelles.",
      "The agent's dilemma: exploit what it knows works or explore new actions to learn. Too much exploitation freezes a mediocre strategy; too much exploration costs dearly in real conditions.",
      see="rl_exploration apprentissage_renforcement_notions"),
    d(T, "embedding_llm", "Plongements de texte et modèles de langage", "Text embeddings and language models", 3,
      "Un plongement transforme un texte en vecteur de nombres qui capte son sens ; un grand modèle de langage (LLM) produit des plongements ou des étiquettes (sentiment, thème). Leur connaissance du passé peut contaminer un backtest (fuite temporelle).",
      "An embedding turns text into a vector of numbers capturing its meaning; a large language model (LLM) produces embeddings or labels (sentiment, topic). Their knowledge of the past can contaminate a backtest (temporal leakage).",
      see="llm_leakage news_sentiment"),
    d(T, "drift_modele", "Dérive d'un modèle (concept drift)", "Model drift (concept drift)", 3,
      "Le lien entre variables et cible change dans le temps (nouveau régime de marché, politique monétaire différente) : un modèle entraîné sur le passé se dégrade. On surveille sa performance récente et on le réentraîne régulièrement.",
      "The link between features and target changes over time (new market regime, different monetary policy): a model trained on the past degrades. Its recent performance is monitored and it is retrained regularly.",
      see="decroissance_alpha live_reliability"),
    d(T, "interpretabilite", "Interprétabilité d'un modèle", "Model interpretability", 3,
      "Capacité à expliquer pourquoi un modèle produit une prévision : coefficients d'une régression, valeurs SHAP, importance par permutation. Elle aide à détecter un modèle qui exploite un artefact plutôt qu'un vrai signal économique.",
      "Ability to explain why a model produces a forecast: regression coefficients, SHAP values, permutation importance. It helps detect a model exploiting an artefact rather than a real economic signal.",
      see="shap importance_permutation"),
    d(T, "probabilite_calibree", "Probabilités calibrées", "Calibrated probabilities", 3,
      "Un modèle est calibré si, parmi les cas où il annonce 70 %, environ 70 % se réalisent. La calibration compte pour dimensionner un pari ; elle se mesure par le score de Brier et l'ECE, et se corrige par régression isotonique ou de Platt.",
      "A model is calibrated if, among cases where it says 70%, about 70% occur. Calibration matters for sizing a bet; it is measured by the Brier score and ECE, and corrected by isotonic or Platt regression.",
      see="calibration brier ece"),
]
